import { useState } from "react";
import { ArrowRightIcon } from "@phosphor-icons/react";
import maqueta from "./maqueta.svg?raw";
import "./maqueta.css";

// Hero "Maqueta viva" (web/DESIGN.md, design lock CO-028): Coyoacán as an architect's model, 529 real H3 hexagons.
// Height = card payment activity, color = where neighborhood commerce is missing, ink pins = tianguis open that day.
// The SVG is generated by web/public/design-lock/maqueta.py from data/processed/ (hex.geojson, tianguis_abierto.json);
// each tianguis marker is a <g class="tg dN"> with N = weekday (0 = lunes … 6 = domingo). No real/simulado chips
// on screen (uak decision CO-028); the data types live in the API and the README.

const NOMBRES = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"];
const LETRAS = ["L", "M", "M", "J", "V", "S", "D"];

// Tianguis open per weekday, counted once from the SVG itself so the number and the pins always agree.
const ABIERTOS = NOMBRES.map((_, d) => (maqueta.match(new RegExp(`class="tg d${d}"`, "g")) ?? []).length);

function hoy(): number {
  return (new Date().getDay() + 6) % 7; // JS: 0 = domingo → our 6
}

export function HeroMaqueta() {
  const [dia, setDia] = useState(hoy);
  return (
    <section className="mq" aria-labelledby="titulo-maqueta">
      <div className="mq-texto">
        <h1 id="titulo-maqueta" className="mq-titulo">
          Así late Coyoacán el <span className="mq-dia">{NOMBRES[dia]}</span>.
        </h1>
        <p className="mq-sub">Cada bloque es un hexágono de la ciudad. Elige un día y mira qué tianguis abren.</p>
        <a href="#/mapa" className="mq-btn">
          Abrir el mapa
          <ArrowRightIcon size={20} weight="bold" aria-hidden="true" />
        </a>
      </div>

      <div className="mq-modelo" data-dia={dia} dangerouslySetInnerHTML={{ __html: maqueta }} />

      <p className="mq-conteo" aria-live="polite">
        <strong>{ABIERTOS[dia]}</strong>
        <span>tianguis abiertos</span>
      </p>

      <div className="mq-dias" role="group" aria-label="Día de la semana">
        <span aria-hidden="true">Día</span>
        <div>
          {LETRAS.map((l, i) => (
            <button key={i} type="button" aria-label={NOMBRES[i]} aria-pressed={dia === i} onClick={() => setDia(i)}>
              {l}
            </button>
          ))}
        </div>
      </div>

      <dl className="mq-leyenda" aria-label="Cómo leer la maqueta">
        <div>
          <dt><i className="mq-l-alto" aria-hidden="true" /></dt>
          <dd>Altura: actividad de pago</dd>
        </div>
        <div>
          <dt><i className="mq-l-color" aria-hidden="true" /></dt>
          <dd>Color: falta comercio</dd>
        </div>
        <div>
          <dt><i className="mq-l-pin" aria-hidden="true" /></dt>
          <dd>Tianguis, datos abiertos CDMX</dd>
        </div>
      </dl>
    </section>
  );
}
